function allocate(totalCents, weights) {
  const sum = weights.reduce((a, b) => a + b, 0);
  if (sum === 0) return weights.map(() => 0);

  const parts = weights.map((w) => Math.floor((totalCents * w) / sum));
  let missing = totalCents - parts.reduce((a, b) => a + b, 0);

  if (missing > 0) {
    const remainders = weights.map((w, i) => ({
      index: i,
      remainder: (totalCents * w) % sum
    }));

    // Sort by remainder descending, then by index ascending
    remainders.sort((a, b) => {
      if (b.remainder !== a.remainder) {
        return b.remainder - a.remainder;
      }
      return a.index - b.index;
    });

    for (let i = 0; i < missing; i++) {
      parts[remainders[i].index]++;
    }
  }

  return parts;
}
