```javascript
  refundOrder(orderId, items, { date, restock = true }) {
    const o = this.getOrder(orderId);

    // Validation
    if (o.status !== 'placed' && o.status !== 'partially_refunded') {
      throw new RefundError(`Order ${orderId} cannot be refunded in status ${o.status}`);
    }
    if (typeof date !== 'string' || !DATE_RE.test(date) || date < o.date) {
      throw new RefundError('Invalid refund date');
    }
    if (!Array.isArray(items) || items.length === 0) {
      throw new RefundError('Items must be a non-empty array');
    }

    // Merge items
    const mergedItems = new Map();
    for (const { sku, qty } of items) {
      if (!Number.isInteger(qty) || qty <= 0) throw new RefundError('Invalid quantity');
      mergedItems.set(sku, (mergedItems.get(sku) ?? 0) + qty);
    }

    // Validate items against order lines
    for (const [sku, qty] of mergedItems) {
      const line = o.lines.find(l => l.sku === sku);
      if (!line) throw new RefundError(`SKU ${sku} not in order`);
      if (qty > (line.qty - line.refundedQty)) {
        throw new RefundError(`Too many units of ${sku} being refunded`);
      }
    }

    // Calculate refund
    const refundLines = [];
    let refundTotalCents = 0;

    for (const [sku, qty] of mergedItems) {
      const line = o.lines.find(l => l.sku === sku);
      const k = qty;
      const totalQty = line.qty;

      let rNet, rTax;
      if (line.refundedQty + k === totalQty) {
        // All units of this line are being refunded
        rNet = line.netCents - line.refundedNetCents;
        rTax = line.taxCents - line.refundedTaxCents;
      } else {
        rNet = roundHalfAwayFromZero(line.netCents * k / totalQty);
        rTax = roundHalfAwayFromZero(line.taxCents * k / totalQty);
      }

      const rTotal = rNet + rTax;
      refundLines.push({ sku, qty: k, netCents: rNet, taxCents: rTax, totalCents: rTotal });
      refundTotalCents += rTotal;

      // Update line running totals
      line.refundedQty += k;
      line.refundedNetCents += rNet;
      line.refundedTaxCents += rTax;
    }

    // Effects
    if (restock) {
      for (const { sku, qty } of mergedItems) {
        this.inventory.release(sku, qty);
      }
    }

    // Update order status
    const allRefunded = o.lines.every(l => l.refundedQty === l.qty);
    o.status = allRefunded ? 'refunded' : 'partially_refunded';

    // Create refund record
    const refundId = `R${String(this.nextRefundNo++).padStart(4, '0')}`;
    const refundRecord = {
      id: refundId,
      orderId: o.id,
      date,
      lines: refundLines,
      totalCents: refundTotalCents
    };
    o.refunds.push(refundRecord);

    return refundRecord;
  }
